PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS requests (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT NOT NULL,depth TEXT DEFAULT 'UNROUTED',state TEXT DEFAULT 'RECEIVED',source_known INTEGER DEFAULT 0,audience_known INTEGER DEFAULT 0,sensitivity_known INTEGER DEFAULT 0,approval_marker TEXT DEFAULT '',scope_marker TEXT DEFAULT '',promotion_status TEXT DEFAULT 'HOLD',authority_status TEXT DEFAULT 'NO',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assets (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,asset_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'CANDIDATE',authority_status TEXT NOT NULL DEFAULT 'NO',promotion_status TEXT NOT NULL DEFAULT 'HOLD');
CREATE TABLE IF NOT EXISTS request_assets (request_id INTEGER NOT NULL,asset_id INTEGER NOT NULL,role TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decisions (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL,decision TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS executions (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL,execution_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'CREATED',output_classification TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receipts (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL,execution_id INTEGER,content TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL,verdict TEXT NOT NULL,next_smallest_action TEXT NOT NULL,promotion_status TEXT DEFAULT 'HOLD',authority_status TEXT DEFAULT 'NO',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS maturation_entries (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL,summary TEXT NOT NULL,next_work_easier_value TEXT NOT NULL,authority_mutation TEXT DEFAULT 'NO',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS next_actions (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL,action TEXT NOT NULL,status TEXT DEFAULT 'HOLD');
CREATE TABLE IF NOT EXISTS guardrail_events (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER,guardrail TEXT NOT NULL,result TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
